 static void savePreset(Context c,JSONObject value,boolean delete,int move){JSONArray saved=stored(c,"ranking_presets_v190"),out=new JSONArray();ArrayList<JSONObject> list=new ArrayList<>();int at=-1;for(int i=0;i<saved.length();i++){JSONObject p=saved.optJSONObject(i);if(p==null)continue;if(p.optString("id").equals(value.optString("id"))){at=list.size();if(delete)continue;p=value;}list.add(p);}if(at<0&&!delete)list.add(value);if(move!=0&&at>=0&&at+move>=0&&at+move<list.size())Collections.swap(list,at,at+move);for(JSONObject p:list)out.put(p);prefs(c).edit().putString("ranking_presets_v190",out.toString()).apply();}
